-- ============================================
-- LUMA — Thème 9 : LONG 1/3 x4 — Une campagne complète sur plusieurs donjons
-- ============================================


update scenarios set content = '{"characters": {"gamemaster": "le maître du jeu", "lyra": "Lyra", "thorne": "Thorne"}, "start_node": "n1", "nodes": {"n1": {"speaker": "gamemaster", "text": "Your party stands before the Crypt of Ashes, first of three trials to reclaim the lost crown.", "text_fr": "Votre groupe se tient devant la Crypte des Cendres, premier des trois défis pour récupérer la couronne perdue.", "choices": [{"text": "Enter cautiously, weapons drawn.", "text_fr": "Entre prudemment, armes dégainées.", "next": "n2"}, {"text": "Let the party''s mage cast a detection spell first.", "text_fr": "Laisse le mage du groupe lancer un sort de détection d''abord.", "next": "n2b"}]}, "n2": {"speaker": "gamemaster", "text": "Inside, skeletal guardians rise from ancient tombs, blocking your path.", "text_fr": "À l''intérieur, des gardiens squelettiques se lèvent d''anciennes tombes, bloquant votre chemin.", "choices": [{"text": "Fight through them directly, trusting your party''s strength.", "text_fr": "Combats-les directement, en faisant confiance à la force de ton groupe.", "next": "n3"}]}, "n2b": {"speaker": "gamemaster", "text": "The spell reveals a hidden trap beside the main path — useful information.", "text_fr": "Le sort révèle un piège caché à côté du chemin principal — une information utile.", "choices": [{"text": "Avoid the trap and proceed carefully around the guardians.", "text_fr": "Évite le piège et avance prudemment autour des gardiens.", "next": "n3"}]}, "n3": {"speaker": "gamemaster", "text": "(After a hard-fought battle) The guardians crumble to dust, revealing the first crown fragment.", "text_fr": "(Après un combat acharné) Les gardiens s''effondrent en poussière, révélant le premier fragment de couronne.", "choices": [{"text": "Take the fragment and press deeper into the crypt.", "text_fr": "Prends le fragment et avance plus profondément dans la crypte.", "next": "n4"}]}, "n4": {"speaker": "lyra", "text": "One fragment down, two to go. This crypt still holds more secrets, I sense it.", "text_fr": "Un fragment de fait, deux à faire. Cette crypte cache encore plus de secrets, je le sens.", "choices": [{"text": "Let''s search the crypt fully before moving to the next dungeon.", "text_fr": "Fouillons la crypte entièrement avant de passer au prochain donjon.", "next": "n5"}, {"text": "We should move quickly — time may not be on our side.", "text_fr": "On devrait avancer vite — le temps n''est peut-être pas de notre côté.", "next": "n5b"}]}, "n5": {"speaker": "gamemaster", "text": "(Thorough search reveals a hidden chamber with valuable supplies.)", "text_fr": "(Une fouille minutieuse révèle une chambre cachée avec des provisions précieuses.)", "choices": [{"text": "Gather the supplies, they''ll help in the trials ahead.", "text_fr": "Rassemble les provisions, elles aideront dans les épreuves à venir.", "next": "n6"}]}, "n5b": {"speaker": "gamemaster", "text": "(You move swiftly, exiting the crypt with the fragment secured.)", "text_fr": "(Vous avancez rapidement, sortant de la crypte avec le fragment sécurisé.)", "choices": [{"text": "Head toward the second trial without delay.", "text_fr": "Dirige-toi vers la deuxième épreuve sans délai.", "next": "n6"}]}, "n6": {"speaker": "gamemaster", "text": "The party arrives at the Sunken Labyrinth, a maze of shifting water passages.", "text_fr": "Le groupe arrive au Labyrinthe Englouti, un dédale de passages d''eau changeants.", "choices": [{"text": "Navigate using the party''s knowledge of tidal patterns.", "text_fr": "Navigue en utilisant la connaissance des marées du groupe.", "next": "n7"}, {"text": "Follow the sound of running water to find the path forward.", "text_fr": "Suis le son de l''eau qui coule pour trouver le chemin.", "next": "n7b"}]}, "n7": {"speaker": "thorne", "text": "The tides shift every hour here — we need to time our movements carefully.", "text_fr": "Les marées changent chaque heure ici — on doit synchroniser nos mouvements soigneusement.", "choices": [{"text": "Wait for the right moment, then move quickly through the passages.", "text_fr": "Attends le bon moment, puis avance vite à travers les passages.", "next": "n8"}]}, "n7b": {"speaker": "gamemaster", "text": "(Following the sound leads you toward a rushing underground river.)", "text_fr": "(Suivre le son vous mène vers une rivière souterraine impétueuse.)", "choices": [{"text": "Follow the river''s path deeper into the labyrinth.", "text_fr": "Suis le chemin de la rivière plus profondément dans le labyrinthe.", "next": "n8"}]}, "n8": {"speaker": "gamemaster", "text": "(After navigating the shifting waters) You reach the second fragment, guarded by a water elemental.", "text_fr": "(Après avoir navigué dans les eaux changeantes) Vous atteignez le deuxième fragment, gardé par un élémentaire d''eau.", "choices": [{"text": "Attempt to reason with the elemental before fighting.", "text_fr": "Essaie de raisonner avec l''élémentaire avant de combattre.", "next": "n9"}, {"text": "Prepare for battle, this creature looks hostile.", "text_fr": "Prépare-toi au combat, cette créature a l''air hostile.", "next": "n9b"}]}, "n9": {"speaker": "gamemaster", "text": "(The elemental pauses, seeming to consider your peaceful approach.)", "text_fr": "(L''élémentaire fait une pause, semblant considérer votre approche pacifique.)", "choices": [{"text": "Offer respect and ask permission to take the fragment.", "text_fr": "Offre du respect et demande la permission de prendre le fragment.", "next": "n10"}]}, "n9b": {"speaker": "gamemaster", "text": "(A fierce battle ensues, testing your party''s coordination and strength.)", "text_fr": "(Une bataille féroce s''ensuit, testant la coordination et la force de votre groupe.)", "choices": [{"text": "Fight together as a unified team to overcome the elemental.", "text_fr": "Combattez ensemble comme une équipe unie pour vaincre l''élémentaire.", "next": "n10"}]}, "n10": {"speaker": "gamemaster", "text": "(Whether through diplomacy or victory, the second fragment is now yours.)", "text_fr": "(Que ce soit par diplomatie ou victoire, le deuxième fragment est maintenant à vous.)", "choices": [{"text": "Two fragments secured. On to the final trial.", "text_fr": "Deux fragments sécurisés. Vers l''épreuve finale.", "next": "n11"}]}, "n11": {"speaker": "gamemaster", "text": "The final trial awaits: the Obsidian Spire, where the last fragment rests atop a perilous climb.", "text_fr": "L''épreuve finale attend : la Flèche d''Obsidienne, où le dernier fragment repose au sommet d''une ascension périlleuse.", "choices": [{"text": "Begin the climb immediately, determined to finish this quest.", "text_fr": "Commence l''ascension immédiatement, déterminé à terminer cette quête.", "next": "n12"}]}, "n12": {"speaker": "lyra", "text": "(Mid-climb) The wind here is fierce — we need to move together, carefully.", "text_fr": "(En pleine ascension) Le vent ici est féroce — on doit avancer ensemble, prudemment.", "choices": [{"text": "Rope yourselves together for safety before continuing.", "text_fr": "Attachez-vous ensemble avec une corde par sécurité avant de continuer.", "next": "n13"}]}, "n13": {"speaker": "gamemaster", "text": "(After a grueling climb, your party reaches the summit, where the final fragment awaits.)", "text_fr": "(Après une ascension éprouvante, votre groupe atteint le sommet, où le fragment final attend.)", "choices": [{"text": "Take the final fragment, completing the crown.", "text_fr": "Prends le fragment final, complétant la couronne.", "next": "n14"}]}, "n14": {"speaker": "gamemaster", "text": "(As the fragments unite, the crown glows brilliantly, its power restored.)", "text_fr": "(Alors que les fragments s''unissent, la couronne brille magnifiquement, son pouvoir restauré.)", "choices": [{"text": "Hold the completed crown high, feeling the weight of this achievement.", "text_fr": "Tiens la couronne complétée haut, sentant le poids de cet accomplissement.", "next": "end_complete"}]}, "end_complete": {"speaker": "thorne", "text": "We did it. Three dungeons, three trials, and now — the crown is finally whole.", "text_fr": "On l''a fait. Trois donjons, trois épreuves, et maintenant — la couronne est enfin complète.", "end": true, "ending_label": "Campagne des trois donjons achevée avec succès 👑⚔️🏆"}}}'::jsonb, is_playable = true
where title = 'Une campagne complète sur plusieurs donjons'
  and theme_id = (select id from scenario_themes where position = 9 and language_id = (select id from languages where code = 'en'));
